### 本题所有可能钱数的集合表示

可达性动态规划保存所有可能状态，不仅保存最大值。例如图中特殊机后能有 $4,23,43$，仅知道最大值四十三，无法判断四元是否可达。位集合用一个比特记录一个数是否存在，左移 $d$ 位就把全部数加 $d$，取或就是合并可能性。本题大多数机器对高钱只做共同加法，所以进一步用偏移表示整组平移；只有至多三十次真正分叉才扫描位集合。

### 思路

![高钱只平移，跨过 20 时交给小钱区](assets/c-shift.svg)

用二十个布尔状态维护币数 $0\ldots19$，其余币数用位集合与共同偏移 $G$ 表示：存储下标 $p$ 对应真实币数 $p-\mathrm{OFFSET}+G$。普通机的增量为 $d=b-a$，所有高钱都够门槛，只修改 $G\gets G+d$；小钱逐个判断是否够钱，并产生本轮新状态。

特殊机在高钱区产生原样、加 $b-a$、加 $c-a$ 三种结果，复制旧位集合后分别移位再取或。小钱同样逐个枚举可用分支。每台处理完，把位集合中已落入 $0\ldots19$ 的值移交小钱区，并删除这些高钱标记；本轮由小钱新产生的高钱最后按新 $G$ 插入，避免重复使用当前机器。

记最大可能币数上界 $M=x+\sum b_i+\sum c_i$，普通机偏移下界为 $-19n$、上界为 $\sum b_i$。代码取足够大的正下标偏置并分配 $L=O(M+20n+\mathrm{OFFSET})$ 个比特，确保偏移后仍能访问。总时间 $O(20n+kL/64+q)$，空间 $O(n+L/64)$ 个机器字。这里位集合长度是带偏置后的 $L$，不能误写成仅 $M$。

### 真实币数、存储下标与本轮读写顺序

初始有四个币，依次经过以下四台实际机器：特殊机 $(a,b,c)=(1,20,40)$，普通机 $(10,3)$，普通机 $(1,20)$，特殊机 $(20,21,23)$。

![四台实际机器使四变四二十三四十三，再变四十六三十六，再变二十三三十五五十五；存储下标和偏移逐项对应，末次两个结果都取同一旧集合](assets/editorial-reasoning/counting17-money-states.svg)

第一台可跳过，或投入一后得到二十、四十，故真实集合为 $\{4,23,43\}$。第二台普通机净变化负七：四不够十，原样保留；二十三、四十三都必须使用，分别变成十六、三十六。共同偏移从零变成负七，原来保存二十三的位现在代表十六，须立刻从高钱位集合清除并移交low。不能让它在下一台仍被当作至少二十的状态。

第三台普通机净增十九，三个状态都够一，得到 $\{23,35,55\}$，共同偏移由负七变成十二。原高钱三十六对应的存储下标不动，现在解释为五十五；旧小钱四、十六的新结果二十三、三十五，要等偏移改完才插入，否则会额外多加十九。

最后一台特殊机可跳过，或净增一、净增三，必须同时读取旧集合 $\{23,35,55\}$。最终恰为九个值：$23,24,26$、$35,36,38$、$55,56,58$；比如二十五不可达，五十八可达。若先加一，再从新结果加三，就会伪造二十七、三十九、五十九，等于同一台机器连用两次。

所有高钱都够任意门槛，但普通机必须用、特殊机仍能跳过；这两种规则不能混成“高钱一律强制兑换”。多条路径到同一币数只合并为存在，不相加概率。输入初值和返还均为正，真实币数不会变成负数，也不会变成零；low预留零号格只是安全的统一表示。

### 参考代码

```cpp
// C. 帮助她玩游戏
// 依次走过 n 台兑换机：普通机只要钱够就必须用；特殊机（至多 30 台）钱够时可以自选用不用，
// 用了还会随机给 b 或 c。问哪些最终钱数「有可能」出现。
//
// 核心：把「所有可能出现的钱数」当成一个集合 S 做 DP。
//   · 钱数 >= 20（所有 a_i 的上界）时，每台机器都一定触发 —— 集合只会整体平移，
//     用一个全局偏移 G 记着，O(1) 搞定，不需要一位一位动。
//   · [1,19] 这 20 个「小钱」单独用 bool 数组存，逐个按阈值判断。
//   · 高钱平移后掉进 [1,19] 的，每台机器后捞出来补进小钱数组。
//   · 特殊机要分叉出「+d」「+e」两份，这才需要真的移位 —— 但特殊机 <= 30 台，
//     每台对位集合做两次移位/或，总代价 = 30 * (值域/64)，可以接受。
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;

static vector<ull> bits;   // 位集合：第 i 位为 1 <=> 真实钱数 (i - OFFSET + G) 可达

static inline void setbit(long long i) { bits[i >> 6] |= 1ULL << (i & 63); }
static inline bool getbit(long long i) { return (bits[i >> 6] >> (i & 63)) & 1ULL; }
static inline void clrbit(long long i) { bits[i >> 6] &= ~(1ULL << (i & 63)); }

// dst |= src << s（整套位集合左移 s 位）
static void orShl(vector<ull> &dst, const vector<ull> &src, int s) {
    if (s <= 0) return;
    int ws = s >> 6, bs = s & 63, W = (int)src.size();
    if (bs == 0) {
        for (int w = W - 1; w >= ws; --w) dst[w] |= src[w - ws];
    } else {
        for (int w = W - 1; w >= ws; --w) {
            ull v = src[w - ws] << bs;
            if (w - ws - 1 >= 0) v |= src[w - ws - 1] >> (64 - bs);
            dst[w] |= v;
        }
    }
}

// dst |= src >> s
static void orShr(vector<ull> &dst, const vector<ull> &src, int s) {
    if (s <= 0) return;
    int ws = s >> 6, bs = s & 63, W = (int)src.size();
    if (bs == 0) {
        for (int w = 0; w + ws < W; ++w) dst[w] |= src[w + ws];
    } else {
        for (int w = 0; w + ws < W; ++w) {
            ull v = src[w + ws] >> bs;
            if (w + ws + 1 < W) v |= src[w + ws + 1] << (64 - bs);
            dst[w] |= v;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    long long x;
    cin >> n >> x >> q;

    vector<int> o(n), a(n), b(n), c(n, 0);
    long long sumB = 0, sumC = 0;
    for (int i = 0; i < n; ++i) {
        cin >> o[i] >> a[i] >> b[i];
        if (o[i] == 1) cin >> c[i];
        sumB += b[i];
        if (o[i] == 1) sumC += c[i];
    }

    // 任意时刻钱数 <= x + 所有 b 之和 + 所有 c 之和
    long long MAXV = x + sumB + sumC;
    // 普通机每台最多把全局偏移拉低 19（b=1,a=20），故 G >= -19n
    const long long OFFSET = 260005;
    long long NB = 19LL * n + 5;
    long long SIZE_BITS = MAXV + NB + OFFSET + 64;
    bits.assign((size_t)(SIZE_BITS >> 6) + 2, 0);

    bool low[20] = {false};       // 可达的「小钱」[0,19]
    long long G = 0;              // 高钱部分的整体偏移：真实值 = 下标 - OFFSET + G

    if (x < 20) low[x] = true;
    else setbit(x - G + OFFSET);

    vector<ull> tmp;
    for (int i = 0; i < n; ++i) {
        int ai = a[i], bi = b[i];
        if (o[i] == 0) {
            // 普通机：小钱逐个按阈值判断；高钱整体平移（只改 G）
            long long d = (long long)bi - ai;
            bool nl[20] = {false};
            long long pend[80];
            int pc = 0;
            for (int v = 0; v < 20; ++v) {
                if (!low[v]) continue;
                if (v >= ai) {                        // 钱够 -> 强制用
                    long long r = v + d;
                    if (r < 20) nl[r] = true; else pend[pc++] = r;
                } else {
                    nl[v] = true;                     // 钱不够 -> 用不了，原地不动
                }
            }
            G += d;                                   // 高钱整体平移
            for (int u = 0; u < 20; ++u) {            // 平移后掉进小钱区的高钱，捞出来
                long long id = u - G + OFFSET;
                if (getbit(id)) { clrbit(id); nl[u] = true; }
            }
            for (int t = 0; t < pc; ++t) setbit(pend[t] - G + OFFSET);
            for (int v = 0; v < 20; ++v) low[v] = nl[v];
        } else {
            // 特殊机：高钱分叉成 原样 / +d / +e 三份；小钱三种选择都列一遍
            long long d = (long long)bi - ai;
            long long e = (long long)c[i] - ai;
            tmp = bits;
            if (d > 0) orShl(bits, tmp, (int)d); else if (d < 0) orShr(bits, tmp, (int)(-d));
            if (e > 0) orShl(bits, tmp, (int)e); else if (e < 0) orShr(bits, tmp, (int)(-e));

            bool nl[20] = {false};
            long long pend[80];
            int pc = 0;
            for (int v = 0; v < 20; ++v) {
                if (!low[v]) continue;
                nl[v] = true;                         // 选择：不用
                if (v >= ai) {                        // 钱够才可以考虑用
                    long long r1 = v + d, r2 = v + e;
                    if (r1 < 20) nl[r1] = true; else pend[pc++] = r1;
                    if (r2 < 20) nl[r2] = true; else pend[pc++] = r2;
                }
            }
            for (int u = 0; u < 20; ++u) {
                long long id = u - G + OFFSET;
                if (getbit(id)) { clrbit(id); nl[u] = true; }
            }
            for (int t = 0; t < pc; ++t) setbit(pend[t] - G + OFFSET);
            for (int v = 0; v < 20; ++v) low[v] = nl[v];
        }
    }

    string out;
    out.reserve((size_t)q * 2 + 2);
    for (int i = 0; i < q; ++i) {
        long long y;
        cin >> y;
        int ok = 0;
        if (y >= 0 && y < 20) ok = low[y] ? 1 : 0;
        else if (y <= MAXV) ok = getbit(y - G + OFFSET) ? 1 : 0;
        out += ok ? "1\n" : "0\n";
    }
    cout << out;
    return 0;
}
```

### 易错点

两个特殊分支都从旧集合生成，不能让第二次移位读取第一次的新结果；负增量要右移。

